    for(var k=0;k<unknown.length;k++){var pivot=k;for(var q=k+1;q<unknown.length;q++)if(Math.abs(A[q][k])>Math.abs(A[pivot][k]))pivot=q;if(Math.abs(A[pivot][k])<1e-12)continue;var tmp=A[k];A[k]=A[pivot];A[pivot]=tmp;var tv=z[k];z[k]=z[pivot];z[pivot]=tv;var div=A[k][k];for(var c=k;c<unknown.length;c++)A[k][c]/=div;z[k]/=div;for(var rr=0;rr<unknown.length;rr++){if(rr===k)continue;var fac=A[rr][k];for(var cc=k;cc<unknown.length;cc++)A[rr][cc]-=fac*A[k][cc];z[rr]-=fac*z[k];}}
